import videojs from 'video.js';
import {
  KEYBOARD_CODES,
  KEYBOARD_KEYS,
  PROGRESSED_BAR_ELEMENT_NAME,
  MEDIA_PROGRESS_LOCAL_STORAGE_FREQUENCY,
  MEDIA_PROGRESS_REMOTE_STORAGE_FREQUENCY,
  MEDIA_RESTRICTION_POST_MESSAGES
} from '@/types/constants';
import { ITooltip } from '@/types/types';
import { ExtendedPlayer } from '@/types/player';
import clientConfig from '@/config';
import { createProgressedElement } from './progressedBar';
import { MediaProgressManager } from './media-progress-manager';

// 99% of duration is considered complete to prevent issues with video replay
const COMPLETION_THRESHOLD = 0.99;

export class MediaRestriction {
  private isMediaProgressReceived = false;
  private progressedTime: number = 0;
  private player: ExtendedPlayer = null;
  private mediaDuration: number;
  private localStorageSetIntervalRef: number;
  private remoteStorageSetIntervalRef: number;
  private tooltipReference: Vue & ITooltip;
  private sourceTypes: string[];
  private readonly isReviewOrPreviewMode: boolean = false;
  private readonly isRtl: boolean = false;
  private readonly mediaId: string | null = null;
  private readonly questionId: string;
  private readonly attemptId: string | null;
  private readonly isVideo: boolean = false;
  private readonly mediaProgressManager: MediaProgressManager;
  private readonly compactTooltip: boolean = false;
  private userX: number;

  constructor(config: {
    isReviewOrPreviewMode: boolean;
    mediaId: string;
    questionId: string;
    attemptId: string;
    isRtl: boolean;
    isVideo: boolean;
    compactTooltip: boolean;
  }) {
    this.isReviewOrPreviewMode = config.isReviewOrPreviewMode;
    this.mediaId = config.mediaId;
    this.questionId = config.questionId;
    this.attemptId = config.attemptId;
    this.isRtl = config.isRtl;
    this.isVideo = config.isVideo;
    this.compactTooltip = config.compactTooltip;

    this.mediaProgressManager = new MediaProgressManager(
      this.questionId,
      this.mediaId,
      this.attemptId,
      this.isReviewOrPreviewMode,
      clientConfig.parentOrigin,
      this.isVideo
    );
  }

  initialize(
    player: ExtendedPlayer,
    {
      tooltipReference,
      sourceTypes
    }: {
      tooltipReference: Vue & ITooltip;
      sourceTypes: string[];
    }
  ): MediaRestriction {
    this.tooltipReference = tooltipReference;
    this.sourceTypes = sourceTypes;
    this.player = player;
    return this;
  }

  apply(): void {
    this.setupClickToPlay();
    this.onInitialDataLoad();
    this.addParentResponseListener();
    this.applyMiddleware();
    this.updateTooltipLayout();
  }

  onPlay(): void {
    if (!this.isReviewOrPreviewMode && !this.isMediaProgressReceived) {
      this.player.pause();
    }

    this.tooltipReference.showTooltip(false);
  }

  private updateProgressedTime(value: number): void {
    // Cap progress at 99% of duration to prevent completion issues
    const maxProgress = this.mediaDuration ? this.mediaDuration * COMPLETION_THRESHOLD : Infinity;
    this.progressedTime = Math.min(Math.ceil(value), maxProgress);
  }

  private get isMediaCompleted(): boolean {
    return this.mediaDuration && this.progressedTime >= this.mediaDuration * COMPLETION_THRESHOLD;
  }

  private readonly updateTooltipLayout = (): void => {
    this.tooltipReference.updateIsRtl(this.isRtl);
    this.tooltipReference.updateMediaType(this.isVideo);
    this.tooltipReference.updateIsCompact(this.compactTooltip);
  };

  private readonly onInitialDataLoad = (): void => {
    this.player.one('loadeddata', async () => {
      this.setMediaDuration();
      this.getMountedProgressedElement();
      if (this.isReviewOrPreviewMode) {
        this.setupEvents();
        this.updateProgressedTime(this.mediaProgressManager.getLocalProgress());
        requestAnimationFrame(() => {
          this.player.currentTime(this.progressedTime);
          this.handleAutoPlay();
        });
        this.setupIntervals();
        return;
      }

      this.mediaProgressManager.requestProgressFromParent();
    });
  };

  private clickToPlayHandler: (event: MouseEvent) => void;

  private readonly handleAutoPlay = async (): Promise<void> => {
    const isAutoPlay = this.player.options_.autoplay;
    if (isAutoPlay) {
      this.player.play();
    }
  };

  private readonly onClickToPlay = (event: MouseEvent) => {
    if (this.isMediaProgressReceived) {
      const mediaElement = event.currentTarget as Element;
      mediaElement.removeEventListener('click', this.clickToPlayHandler);
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    this.mediaProgressManager.requestProgressFromParent();
  };

  private readonly setupClickToPlay = (): void => {
    if (this.isReviewOrPreviewMode) {
      return;
    }

    const mediaElement = document.querySelector('.vjs-tech');

    this.clickToPlayHandler = this.onClickToPlay.bind(this);
    mediaElement.addEventListener('click', this.clickToPlayHandler);
  };

  private setMediaDuration(): void {
    this.mediaDuration = Math.floor(this.player.duration());
  }

  private readonly updateProgressedElement = (): void => {
    const progressedElement: HTMLElement = this.getMountedProgressedElement();
    const widthValue = Math.min((this.progressedTime / this.mediaDuration) * 100, 100);

    progressedElement.style.width = `${widthValue}%`;
  };

  private readonly getMountedProgressedElement = (): HTMLElement => {
    let progressedElement: HTMLElement | null = document.getElementById(`${PROGRESSED_BAR_ELEMENT_NAME}`);

    if (!progressedElement) {
      progressedElement = createProgressedElement();
      this.player.controlBar.progressControl.seekBar.el().appendChild(progressedElement);
    }

    return progressedElement;
  };

  private readonly onParentResponseHandler = (event: MessageEvent) => {
    const { type, value } = event.data;

    if (type === MEDIA_RESTRICTION_POST_MESSAGES.PROGRESS_RESPONSE) {
      this.updateProgressedTime(Math.max(value, this.mediaProgressManager.getLocalProgress()));
      if (this.player) {
        requestAnimationFrame(() => {
          this.player.currentTime(this.progressedTime);
          this.handleAutoPlay();
        });
      }
      this.isMediaProgressReceived = true;
      this.updateProgressedElement();
      this.setupEvents();

      const isEffectivelyComplete = this.mediaDuration && value >= this.mediaDuration * COMPLETION_THRESHOLD;
      if (isEffectivelyComplete) {
        this.mediaProgressManager.saveProgress(value);
        this.mediaProgressManager.notifyCompletionToParent();
        this.enablePictureInPicture();
        return;
      }

      this.setupIntervals();
    }

    if ((type === MEDIA_RESTRICTION_POST_MESSAGES.PAUSE_VIDEO || type === MEDIA_RESTRICTION_POST_MESSAGES.PAUSE_AUDIO) && this.player) {
      this.player.pause();
    }
  };

  private readonly addParentResponseListener = (): void => {
    window.addEventListener('message', this.onParentResponseHandler);
  };

  private readonly setupEvents = (): void => {
    const progressControl = this.player.controlBar.progressControl;

    this.player.on('timeupdate', this.onTimeUpdate);
    this.player.on('fullscreenchange', this.onFullScreenChange);

    progressControl.on('mousemove', this.onMouseMove);
    progressControl.on('mouseleave', this.onMouseLeave);

    progressControl.on('touchmove', this.onTouchMove);
    progressControl.on('touchend', this.onTouchEnd);

    this.player.on('keydown', this.onKeyDown);

    this.player.on('contextmenu', this.onRightClick);
  };

  private readonly dispose = (): void => {
    const progressControl = this.player.controlBar.progressControl;

    this.player.off('timeupdate', this.onTimeUpdate);
    this.player.off('fullscreenchange', this.onFullScreenChange);

    progressControl.off('mousemove', this.onMouseMove);
    progressControl.off('mouseleave', this.onMouseLeave);

    progressControl.off('touchmove', this.onTouchMove);
    progressControl.off('touchend', this.onTouchEnd);

    this.player.off('keydown', this.onKeyDown);

    this.player.off('contextmenu', this.onRightClick);

    this.enablePictureInPicture();

    window.removeEventListener('message', this.onParentResponseHandler);

    this.clearIntervals();
  };

  private readonly enablePictureInPicture = () => {
    const mediaElement = this.player.tech().el();
    mediaElement.removeAttribute('disablePictureInPicture');
  };

  private readonly onTimeUpdate = (): void => {
    if (!this.player) {
      return;
    }
    this.updateProgressedTime(Math.max(Math.ceil(this.player.currentTime()), this.progressedTime));
    this.updateProgressedElement();
    if (this.userX) {
      const isHoveringPastCurrentTime = this.getIsHoveringPastCurrentTime(this.userX);
      this.tooltipReference.showTooltip(isHoveringPastCurrentTime);
      this.updateCursorStyle(isHoveringPastCurrentTime);
    }

    if (this.player && this.player.paused()) {
      this.mediaProgressManager.saveProgress(this.progressedTime);
    }

    if (this.isMediaCompleted) {
      if (this.player) {
        this.player.play();
      }
      this.mediaProgressManager.saveProgress(this.progressedTime);
      this.mediaProgressManager.notifyCompletionToParent();
      this.dispose();
    }
  };

  private readonly getTimeTooltipRect = (isTouchMove: boolean, userX: number): Partial<DOMRect> => {
    const seekBar = this.player.controlBar.progressControl.seekBar;
    const seekBarRect = seekBar.el().getBoundingClientRect();

    return isTouchMove
      ? this.getTouchMoveTimeTooltipRect(seekBarRect, userX)
      : seekBar.mouseTimeDisplay.el().getBoundingClientRect();
  };

  private readonly getTouchMoveTimeTooltipRect = (seekBarRect: DOMRect, userX: number): Partial<DOMRect> => {
    let tooltipLeftValue = 0;

    if (userX + this.tooltipReference.tooltipOffsetWidth / 2 >= window.document.body.clientWidth) {
      tooltipLeftValue = window.document.body.clientWidth - this.tooltipReference.tooltipOffsetWidth / 2;
    } else {
      tooltipLeftValue = userX;
    }

    return {
      left: tooltipLeftValue,
      width: seekBarRect.width,
      top: seekBarRect.top
    };
  };

  private readonly updateCursorStyle = (isHoveringPastCurrentTime: boolean): void => {
    const progressControl = this.player.controlBar.progressControl;
    const seekBar = progressControl.seekBar;
    const playProgressBar = seekBar.playProgressBar;
    const cursorStyle = isHoveringPastCurrentTime ? 'not-allowed' : 'pointer';
    progressControl.el().style.cursor = cursorStyle;
    seekBar.el().style.cursor = cursorStyle;
    playProgressBar.el().style.cursor = cursorStyle;
  };

  private readonly getIsHoveringPastCurrentTime = (userX: number): boolean => {
    const progressControl = this.player.controlBar.progressControl;
    const seekBar = progressControl.seekBar;
    const progressedElement: HTMLElement = this.getMountedProgressedElement();
    const currentTime = (+progressedElement.style.width.slice(0, -1) / 100) * this.mediaDuration;
    const seekBarRect = seekBar.el().getBoundingClientRect();
    const userXValue = userX - seekBarRect.left;
    const hoverTime = (userXValue / seekBarRect.width) * this.mediaDuration;
    return hoverTime >= currentTime;
  };

  private readonly tooltipHandler = (userX: number, isTouchMove?: boolean): void => {
    const isHoveringPastCurrentTime = this.getIsHoveringPastCurrentTime(userX);

    this.tooltipReference.showTooltip(isHoveringPastCurrentTime);

    this.updateCursorStyle(isHoveringPastCurrentTime);

    if (isHoveringPastCurrentTime) {
      const timeTooltipRect: Partial<DOMRect> = this.getTimeTooltipRect(isTouchMove, userX);
      this.tooltipReference.updateTooltipPosition(timeTooltipRect as DOMRect, Boolean(isTouchMove));
    }
  };

  private readonly onMouseMove = (event: { clientX: number }): void => {
    this.userX = event.clientX;
    this.tooltipHandler(event.clientX);
  };

  private readonly onMouseLeave = (): void => {
    this.userX = null;
    this.tooltipReference.showTooltip(false);
  };

  private readonly onTouchMove = (event: TouchEvent): void => {
    this.tooltipHandler(event.touches[0].clientX, true);
  };

  private readonly onTouchEnd = (): void => {
    this.tooltipReference.showTooltip(false);
  };

  private readonly onFullScreenChange = (): void => {
    if (this.player.isFullscreen()) {
      this.tooltipReference.appendToParent(this.player.el());
    } else {
      this.tooltipReference.appendToParent(document.body);
    }
  };

  private readonly onKeyDown = (event: KeyboardEvent) => {
    if (+event.code === KEYBOARD_CODES.RIGHT_KEY_CODE || event.key === KEYBOARD_KEYS.RIGHT_KEY) {
      event.preventDefault();
      event.stopPropagation();
    }
  };

  private readonly onRightClick = (event: MouseEvent) => {
    event.preventDefault();
  };

  private readonly setupUpdateLocalStorageMediaProgress = (): void => {
    if (this.player.paused()) {
      return;
    }

    this.mediaProgressManager.saveProgressToLocal(this.progressedTime);
  };

  private readonly updateRemoteMediaProgress = (): void => {
    if (this.player.paused()) {
      return;
    }

    this.mediaProgressManager.sendProgressToParent(this.progressedTime);
  };

  private readonly setupIntervals = (): void => {
    this.localStorageSetIntervalRef = setInterval(
      this.setupUpdateLocalStorageMediaProgress,
      MEDIA_PROGRESS_LOCAL_STORAGE_FREQUENCY
    );
    if (this.isReviewOrPreviewMode) {
      return;
    }
    this.remoteStorageSetIntervalRef = setInterval(
      this.updateRemoteMediaProgress,
      MEDIA_PROGRESS_REMOTE_STORAGE_FREQUENCY
    );
  };

  private readonly clearIntervals = (): void => {
    clearInterval(this.remoteStorageSetIntervalRef);
    clearInterval(this.localStorageSetIntervalRef);
  };

  private readonly restrictForwardSeeking = (): unknown => {
    return {
      setCurrentTime: (currentTime: number): number => {
        return Math.min(currentTime, this.progressedTime);
      }
    };
  };

  private applyMiddleware(): void {
    this.sourceTypes.forEach(type => {
      videojs.use(type, this.restrictForwardSeeking);
    });
  }
}
