


















import { Component, Vue } from 'vue-property-decorator';
import Player from '@/view/Player.vue';
import Spinner from '@/components/Spinner.vue';
import { PLAYER_RENDER_RETRY_COUNT } from '@/types/constants';
import { MediaFileInfo } from '@/types/media';
import toBoolean from '@/utils/toBoolean';
import sleep from '@/utils/sleep';
import { notifyStatusToParent, sendPostMessage } from '@/utils/utils';
import { extractPlayerOptions } from '@/utils/queryStringParser';
import { MediaService } from '@/services/MediaService';
import clientConfig from '@/config';

const keepLoaderMs = 500;
@Component({
  components: { Player, Spinner }
})
export default class App extends Vue {
  mediaFileInfo: MediaFileInfo = null;
  requestPending: boolean = true;
  queryStringOptions: any = extractPlayerOptions(window.location.search);
  parsedStyledVariables: any;
  isVideo: boolean = true;
  spinnerColor: string;
  rerenderCount = 0;
  isOffline = false;

  async beforeMount() {
    const { video, source, style_variables, mode, thumbnail, autoplay, courseId, publishMode } =
      this.queryStringOptions;
    this.isVideo = toBoolean(video);
    this.parsedStyledVariables = style_variables && JSON.parse(style_variables);
    this.spinnerColor = this.parsedStyledVariables && this.parsedStyledVariables['@main-color'];
    this.isOffline = mode === 'offline';

    this.mediaFileInfo = await MediaService.getMediaFileInfo({
      isVideo: this.isVideo,
      isOffline: this.isOffline,
      source,
      thumbnail,
      courseId,
      publishMode
    });

    if (window.parent && this.mediaFileInfo.isPortrait) {
      sendPostMessage(
        window.parent,
        {
          type: 'portrait-video',
          data: {
            source
          }
        },
        clientConfig.parentOrigin
      );
    }

    notifyStatusToParent(this.mediaFileInfo.status);

    // this delay is added to allow the player-client to override the chromium browser's audio rendering
    // for voice-overs which are automatically played.
    if (autoplay === '1') {
      await sleep(keepLoaderMs);
    }

    this.requestPending = false;
  }

  handleRerender() {
    if (this.rerenderCount <= PLAYER_RENDER_RETRY_COUNT) {
      this.rerenderCount += 1;
    }
  }
}
