import Vue from 'vue';
import App from '@/App.vue';
import Player from '@/view/Player.vue';
import { SUPPORTED_LANGUAGES_CODES } from '@/types/constants';
import config from '@/config';
import { getQueryStringParamByName } from '@/utils/queryStringParser';

import { initialize as initializeSdk, Localization, utils } from '@easygenerator/fragment-sdk';

Vue.config.productionTip = false;
let instance: Vue;

const fragmentName = 'player';

async function initialize() {
  const translationManager = utils.TranslationManager.getInstance();
  const locale = translationManager.getCurrentLocale();
  await translationManager.initialize({
    path: './localization/lang',
    supportedLangs: SUPPORTED_LANGUAGES_CODES,
    locale: getQueryStringParamByName('lang') || locale || '',
    options: {
      useCacheBuster: false,
      query: {
        _: config.version
      }
    }
  });

  initializeSdk({ localize: translationManager.localize, initializePermissions: false });

  Vue.use(Localization);
  Vue.component('player', Player);
}
function render(element: Element) {
  document.body.classList.add(fragmentName);

  instance = new Vue({
    render: (h: any) => h(App),
    renderError(h: any, err: any) {
      return h('pre', { style: { color: 'red' } }, err.stack);
    }
  });

  instance.$mount(element);
}

function destroy() {
  document.body.classList.remove(fragmentName);
  if (instance) {
    instance.$destroy();
  }
}

export { initialize, render, destroy };
