<template>
  <div
    role="tooltip"
    tabindex="0"
    aria-live="assertive"
    id="tooltip-container"
    :class="{ compact: isCompact }"
    :style="{ display: isVisible ? 'flex' : 'none' }"
  >
    <div
      id="tooltip-elements-container"
      :style="{ flexDirection: isRtl ? 'row-reverse' : 'row' }"
    >
      <svg
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
      >
        <g id="icon/lock">
          <rect
            width="16"
            height="16"
            fill="white"
          />
          <g id="Group 1899">
            <path
              id="Vector"
              d="M11.64 6.4668H3.96C3.4298 6.4668 3 6.85482 3 7.33346V12.5335C3 13.0121 3.4298
                13.4001 3.96 13.4001H11.64C12.1702 13.4001 12.6 13.0121 12.6 12.5335V7.33346C12.6 6.85482
                12.1702 6.4668 11.64 6.4668Z"
              stroke="#363E4E"
              stroke-width="1.2"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
            <path
              id="Vector_2"
              d="M11.4012 6.46665C11.4012 5.54724 11.0219 4.66548 10.3468 4.01536C9.67162
                3.36524 8.75595 3 7.80117 3C6.84639 3 5.93072 3.36524 5.25559 4.01536C4.58046 4.66548 4.20117
                5.54724 4.20117 6.46665"
              stroke="#363E4E"
              stroke-width="1.2"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </g>
        </g>
      </svg>
      <h3
        id="tooltip-text-element"
        :aria-label="isVideo ? $t('cannot-skip-video') : $t('cannot-skip-audio')"
      >
        {{ isVideo ? $t('cannot-skip-video') : $t('cannot-skip-audio') }}
      </h3>
    </div>
  </div>
</template>

<script>
const TOOLTIP_PRIMARY_FONT_FAMILY = 'Qanelas-Soft';

export default {
  name: 'Tooltip',
  data() {
    return {
      isVisible: false,
      tooltipOffsetWidth: 195,
      tooltipOffsetHeight: 50,
      compactTooltipOffsetHeight: 26,
      isRtl: false,
      isVideo: false,
      isCompact: false
    };
  },
  mounted() {
    this.adjustFontSizeBasedOnFontFamily(TOOLTIP_PRIMARY_FONT_FAMILY);
  },
  methods: {
    updateIsRtl(isRtl) {
      this.isRtl = isRtl;
    },
    updateMediaType(isVideo) {
      this.isVideo = isVideo;
    },
    updateIsCompact(isCompact) {
      this.isCompact = isCompact;
    },
    appendToParent(parentElement) {
      parentElement.appendChild(this.$el);
    },
    showTooltip(show) {
      this.isVisible = show;
    },
    updateTooltipPosition(timeTooltipRect, isTouchMove) {
      const gap = 30;
      let tooltipLeftPositionValue = timeTooltipRect.left - this.tooltipOffsetWidth / 2;
      tooltipLeftPositionValue += !isTouchMove ? timeTooltipRect.width / 2 : 0;

      this.$el.style.left = `${tooltipLeftPositionValue}px`;
      if (this.isCompact) {
        this.$el.style.top = `${timeTooltipRect.top - this.compactTooltipOffsetHeight * 2}px`;
      } else {
        this.$el.style.top = `${timeTooltipRect.top - this.tooltipOffsetHeight - gap}px`;
      }
    },

    adjustFontSizeBasedOnFontFamily(fontFamily) {
      const tooltipTextElement = this.$el.querySelector('#tooltip-text-element');
      const computedStyle = getComputedStyle(tooltipTextElement);

      const appliedFontFamily = computedStyle.fontFamily;

      tooltipTextElement.style.fontSize = appliedFontFamily.includes(fontFamily) ? '12px' : '11px';
    }
  }
};
</script>

