import TranslationManager from '@easygenerator/fragment-sdk/dist/utils/TranslationManager';
import { extractPlayerOptions } from './queryStringParser';
import { utils } from '@easygenerator/fragment-sdk';
import { CDN_HOSTNAME, SUPPORTED_LANGUAGES_LIST } from '@/types/constants';

export function getNameByLangCode(code: string): string {
  if (!code || code === 'unk') {
    return TranslationManager.getInstance().localize('subtitleUnknownLanguage');
  }

  const lang = SUPPORTED_LANGUAGES_LIST.find(i => i.code === code);
  if (lang) {
    return lang.label;
  }

  return code;
}

export function numerate() {
  const dict = {};

  return (name: string) => {
    if (!dict[name]) {
      dict[name] = 1;
      return name;
    }

    dict[name]++;
    return `${name} ${dict[name]}`;
  };
}

export function notifyStatusToParent(status: string) {
  const { source, origin } = extractPlayerOptions(window.location.search);
  if (origin && source && status && window.parent) {
    window.parent.postMessage({ type: 'media-status-changed', source, status }, origin);
  }
}

export function isCdnUrl(sourceUrl: string) {
  return utils.UrlHelper.isUrl(sourceUrl) && new URL(sourceUrl).hostname === CDN_HOSTNAME;
}

export function sendPostMessage(parentWindow: Window, payload: unknown, parentOrigin: string) {
    parentWindow.postMessage(payload, parentOrigin);
}
